1	// Combines local provider pricing + Artificial Analysis benchmark data into
2	// per-category recommendations.
3	
4	import { readFile, writeFile, mkdir } from "node:fs/promises";
5	import path from "node:path";
6	
7	export type Provider = "copilot" | "opencode-go";
8	
9	interface Candidate {
10	  provider: Provider;
11	  model: string;
12	  priceInput: number;
13	  priceOutput: number;
14	}
15	
16	export interface MappingEntry {
17	  provider: Provider;
18	  providerModel: string;
19	  aaSlug: string | null;
20	  note?: string;
21	}
22	
23	export interface AaModel {
24	  id: string;
25	  name: string;
26	  slug: string;
27	  evaluations: {
28	    artificial_analysis_intelligence_index?: number | null;
29	    artificial_analysis_coding_index?: number | null;
30	    artificial_analysis_agentic_index?: number | null;
31	  };
32	  performance?: {
33	    median_output_tokens_per_second?: number | null;
34	  };
35	}
36	
37	interface CategoryWeights {
38	  agenticIndex?: number;
39	  codingIndex?: number;
40	  intelligenceIndex?: number;
41	  costEfficiency?: number;
42	  speed?: number;
43	}
44	
45	interface BlacklistEntry {
46	  match: string;
47	  reason: string;
48	}
49	
50	interface ScoredCandidate {
51	  provider: Provider;
52	  model: string;
53	  aaSlug: string;
54	  score: number;
55	  breakdown: Record<string, number>;
56	  priceBlendedPer1M: number;
57	}
58	
59	const OUTPUT_OUTPUT_TO_INPUT_RATIO = 3; // assume 3 output tokens per 1 input token (typical agentic workload)
60	
61	function blendedPrice(priceInput: number, priceOutput: number): number {
62	  const totalParts = 1 + OUTPUT_OUTPUT_TO_INPUT_RATIO;
63	  return (priceInput * 1 + priceOutput * OUTPUT_OUTPUT_TO_INPUT_RATIO) / totalParts;
64	}
65	
66	// Strips variant qualifiers like " (<= 256K tokens)", " (Off-Peak)", " (Peak)" so
67	// tiered/peak pricing rows collapse to one representative candidate per base model.
68	export function baseModelName(model: string): string {
69	  let stripped = model;
70	  while (/\s*\([^)]*\)\s*$/.test(stripped)) {
71	    stripped = stripped.replace(/\s*\([^)]*\)\s*$/, "").trim();
